#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(i2c_emul, CONFIG_I2C_DRIVER_LOG_LEVEL);

static int i2c_emul_transfer(const struct device *dev, struct i2c_msg *msgs,
			     uint8_t num_msgs, uint16_t addr)
{
	struct i2c_emul_data *data = dev->data;
	const struct i2c_emul_api *api = dev->api;

	return api->transfer(data, msgs, num_msgs, addr);
}

static const struct i2c_driver_api i2c_emul_api = {
	.transfer = i2c_emul_transfer,
};

int i2c_emul_init(const struct device *dev, struct i2c_emul *emul,
		  const struct i2c_emul_api *api, struct i2c_emul_data *data)
{
	if (emul == NULL || api == NULL || data == NULL) {
		return -EINVAL;
	}

	emul->api = api;
	emul->data = data;

	return 0;
}

#ifdef CONFIG_I2C_EMUL_RUNTIME_CONFIGURE
int i2c_emul_set_api(const struct device *dev, const struct i2c_emul_api *api)
{
	struct i2c_emul_data *data = dev->data;

	if (api == NULL) {
		return -EINVAL;
	}

	data->api = api;

	return 0;
}

int i2c_emul_set_data(const struct device *dev, struct i2c_emul_data *data)
{
	struct i2c_emul_data *emul_data = dev->data;

	if (data == NULL) {
		return -EINVAL;
	}

	emul_data = data;

	return 0;
}
#endif /* CONFIG_I2C_EMUL_RUNTIME_CONFIGURE */

#define I2C_EMUL_DT_DEFINE(n) \
	static struct i2c_emul_data i2c_emul_data_##n; \
	static const struct i2c_emul_api i2c_emul_api_##n = { \
		.transfer = DT_INST_PROP(n, i2c_emul_transfer_fn), \
	}; \
	DEVICE_DT_INST_DEFINE(n, i2c_emul_init, NULL, \
			      &i2c_emul_data_##n, &i2c_emul_api_##n, \
			      POST_KERNEL, CONFIG_I2C_INIT_PRIORITY, \
			      &i2c_emul_api);

DT_INST_FOREACH_STATUS_OKAY(I2C_EMUL_DT_DEFINE)
